     1→import { Screen } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import { Membership, type RoomInfo } from "@unomed/react-native-matrix-sdk";
     4→import { MatrixService } from "modules/matrix-client/services";
     5→import { useRoomInitialization } from "modules/timeline/hooks";
     6→import { useEffect, useMemo, useState } from "react";
     7→import { useSafeAreaInsets } from "react-native-safe-area-context";
     8→import { Loading } from "shared/components";
     9→import { RoomHeader, RoomInvite, RoomTimeline } from "./fragments";
    10→
    11→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
    12→  route,
    13→  navigation,
    14→}) => {
    15→  const { roomId } = route.params;
    16→  const client = MatrixService.instance;
    17→  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
    18→  const insets = useSafeAreaInsets();
    19→  const hasActiveCall = useMemo(() => room?.hasActiveRoomCall(), [room]);
    20→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
    21→  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
    22→  const isRoomInvite = useMemo(() => {
    23→    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
    24→  }, [roomInfo, isInviteAccepted]);
    25→
    26→  const { roomMembers, hasNoCallOption } = useRoomInitialization({ room });
    27→
    28→  useEffect(() => {
    29→    room?.roomInfo().then(setRoomInfo).catch(console.error);
    30→  }, [room]);
    31→
    32→  const handleStartCall = () => {
    33→    if (!client || !room) {
    34→      console.error("Client or room not available");
    35→      return;
    36→    }
    37→
    38→    navigation.navigate("elementCall", {
    39→      roomId,
    40→      roomName: room.displayName(),
    41→    });
    42→  };
    43→
    44→  const handleInviteAccepted = () => {
    45→    setIsInviteAccepted(true);
    46→  };
    47→
    48→  const handleInviteDeclined = () => {
    49→    navigation.goBack();
    50→  };
    51→
    52→  const handleRoomDetails = () => {
    53→    if (isRoomInvite || !room) return;
    54→    navigation.navigate("roomDetails", { room });
    55→  };
    56→
    57→  if (!room) return null;
    58→
    59→  if (!roomInfo) {
    60→    return (
    61→      <Screen hideTopSafeArea scrollable={false}>
    62→        <RoomHeader
    63→          room={room}
    64→          roomMembers={roomMembers}
    65→          hasActiveCall={false}
    66→          hasNoCallOption
    67→          topInset={insets.top}
    68→          onBack={() => navigation.goBack()}
    69→        />
    70→        <Loading isFullScreen={false} />
    71→      </Screen>
    72→    );
    73→  }
    74→
    75→  return (
    76→    <Screen hideTopSafeArea>
    77→      <RoomHeader
    78→        room={room}
    79→        roomMembers={roomMembers}
    80→        hasActiveCall={hasActiveCall ?? false}
    81→        hasNoCallOption={isRoomInvite || hasNoCallOption}
    82→        topInset={insets.top}
    83→        onBack={() => navigation.goBack()}
    84→        onRoomDetails={handleRoomDetails}
    85→        onStartCall={handleStartCall}
    86→      />
    87→
    88→      {isRoomInvite ? (
    89→        <RoomInvite
    90→          roomId={roomId}
    91→          roomInfo={roomInfo}
    92→          onAccepted={handleInviteAccepted}
    93→          onDeclined={handleInviteDeclined}
    94→        />
    95→      ) : (
    96→        <RoomTimeline room={room} roomId={roomId} />
    97→      )}
    98→    </Screen>
    99→  );
   100→};
