     1→import {
     2→  MessageLikeEventContent_Tags,
     3→  type MessageType,
     4→  MessageType_Tags,
     5→  NotificationEvent_Tags,
     6→  type NotificationItem,
     7→  TimelineEventType_Tags,
     8→} from "@unomed/react-native-matrix-sdk";
     9→import { MatrixService } from "modules/matrix-client/services/matrix-service";
    10→
    11→type FormattedNotification = {
    12→  title: string;
    13→  message: string;
    14→  room_id: string;
    15→};
    16→
    17→/** Get the decrypted content of an encrypted event*/
    18→export const getDecryptedEventContent = async (
    19→  roomId: string,
    20→  eventId: string,
    21→): Promise<string | null> => {
    22→  try {
    23→    const notificationClient =
    24→      MatrixService.getNotificationClient() ||
    25→      (await MatrixService.ensureNotificationClient());
    26→    if (!notificationClient) return null;
    27→
    28→    const item = await MatrixService.getNotificationContent(roomId, eventId);
    29→    if (!item) return null;
    30→
    31→    return getNotificationItemContent(item);
    32→  } catch (error) {
    33→    console.warn("Failed to get decrypted event content:", error);
    34→    return null;
    35→  }
    36→};
    37→
    38→const formatMessageType = (messageType: MessageType): string | null => {
    39→  if (!messageType) return null;
    40→
    41→  switch (messageType.tag) {
    42→    case MessageType_Tags.Text:
    43→    case MessageType_Tags.Emote:
    44→    case MessageType_Tags.Notice:
    45→      return messageType.inner.content.body || "Message";
    46→    case MessageType_Tags.Image:
    47→      return "📷 Image";
    48→    case MessageType_Tags.Video:
    49→      return "🎥 Video";
    50→    case MessageType_Tags.Audio:
    51→      return "🎵 Audio";
    52→    case MessageType_Tags.File:
    53→      return "📎 File";
    54→    case MessageType_Tags.Location:
    55→      return "📍 Location";
    56→    case MessageType_Tags.Gallery:
    57→      return "📷 Gallery";
    58→    default:
    59→      return null;
    60→  }
    61→};
    62→
    63→const getNotificationItemContent = (item: NotificationItem): string | null => {
    64→  if (item.event.tag !== NotificationEvent_Tags.Timeline) return null;
    65→
    66→  const eventType = item.event.inner.event.eventType();
    67→  if (eventType.tag !== TimelineEventType_Tags.MessageLike) return null;
    68→
    69→  const content = eventType.inner.content;
    70→
    71→  switch (content.tag) {
    72→    case MessageLikeEventContent_Tags.RoomMessage:
    73→      return formatMessageType(content.inner.messageType) || "Message";
    74→    case MessageLikeEventContent_Tags.RoomEncrypted:
    75→      return null;
    76→    case MessageLikeEventContent_Tags.Sticker:
    77→      return "🧩 Sticker";
    78→    case MessageLikeEventContent_Tags.Poll:
    79→      return "📊 Poll";
    80→    case MessageLikeEventContent_Tags.ReactionContent:
    81→      return "Reacted to a message";
    82→    case MessageLikeEventContent_Tags.RoomRedaction:
    83→      return "Message deleted";
    84→    case MessageLikeEventContent_Tags.CallInvite:
    85→    case MessageLikeEventContent_Tags.RtcNotification:
    86→      return "Incoming call";
    87→    case MessageLikeEventContent_Tags.CallHangup:
    88→      return "Call ended";
    89→    default:
    90→      return null;
    91→  }
    92→};
    93→
    94→/** Check if a decrypted notification item is a call event (CallInvite or RtcNotification) */
    95→const isNotificationItemCall = (item: NotificationItem): boolean => {
    96→  if (item.event.tag !== NotificationEvent_Tags.Timeline) return false;
    97→
    98→  const eventType = item.event.inner.event.eventType();
    99→  if (eventType.tag !== TimelineEventType_Tags.MessageLike) return false;
   100→
   101→  const content = eventType.inner.content;
   102→  return (
   103→    content.tag === MessageLikeEventContent_Tags.CallInvite ||
   104→    content.tag === MessageLikeEventContent_Tags.RtcNotification
   105→  );
   106→};
   107→
   108→/** Check if an encrypted event is a call after decryption */
   109→export const isDecryptedEventCall = async (
   110→  roomId: string,
   111→  eventId: string,
   112→): Promise<boolean> => {
   113→  try {
   114→    const notificationClient =
   115→      MatrixService.getNotificationClient() ||
   116→      (await MatrixService.ensureNotificationClient());
   117→    if (!notificationClient) return false;
   118→
   119→    const item = await MatrixService.getNotificationContent(roomId, eventId);
   120→    if (!item) return false;
   121→
   122→    return isNotificationItemCall(item);
   123→  } catch (error) {
   124→    console.warn("Failed to check if decrypted event is call:", error);
   125→    return false;
   126→  }
   127→};
   128→
   129→/** Format notification message content based on message type */
   130→const formatMessageContent = (data: NotificationData): string => {
   131→  const senderName = data.sender_display_name || data.sender || "Someone";
   132→  const msgType = data.content_msgtype;
   133→
   134→  switch (msgType) {
   135→    case "m.text":
   136→      return `${senderName}: ${data.content_body || "Message"}`;
   137→    case "m.image":
   138→      return `${senderName}: 📷 Image`;
   139→    case "m.video":
   140→      return `${senderName}: 🎥 Video`;
   141→    case "m.audio":
   142→      return `${senderName}: 🎵 Audio`;
   143→    case "m.file":
   144→      return `${senderName}: 📎 File`;
   145→    case "m.location":
   146→      return `${senderName}: 📍 Location`;
   147→    case "m.emote":
   148→      return `${senderName}: ${data.content_body || "Emote"}`;
   149→    case "m.notice":
   150→      return `${senderName}: ${data.content_body || "Notice"}`;
   151→    default:
   152→      return `${senderName}: ${data.content_body || "Message"}`;
   153→  }
   154→};
   155→
   156→export const formatLocalPushNotificationMessage = (
   157→  data: NotificationData | undefined,
   158→): FormattedNotification | undefined => {
   159→  if (!data) return;
   160→
   161→  const senderName = data.sender_display_name || data.sender || "Unknown";
   162→  const roomTitle = data.room_name || data.room_id || "Unknown Room";
   163→
   164→  // Handle membership events
   165→  if (data.type === "m.room.member") {
   166→    if (data?.membership === "invite") {
   167→      return {
   168→        title: senderName,
   169→        message: `${senderName} invited you to a room`,
   170→        room_id: data.room_id || "",
   171→      };
   172→    }
   173→    if (data?.membership === "join") {
   174→      return {
   175→        title: roomTitle,
   176→        message: `${senderName} joined the room`,
   177→        room_id: data.room_id || "",
   178→      };
   179→    }
   180→    if (data?.membership === "leave") {
   181→      return {
   182→        title: roomTitle,
   183→        message: `${senderName} left the room`,
   184→        room_id: data.room_id || "",
   185→      };
   186→    }
   187→    if (data?.membership === "ban") {
   188→      return {
   189→        title: roomTitle,
   190→        message: `${senderName} was banned from the room`,
   191→        room_id: data.room_id || "",
   192→      };
   193→    }
   194→    if (data?.membership === "kick") {
   195→      return {
   196→        title: roomTitle,
   197→        message: `${senderName} was removed from the room`,
   198→        room_id: data.room_id || "",
   199→      };
   200→    }
   201→    return undefined;
   202→  }
   203→
   204→  // Handle encrypted messages (fallback - will be overridden if decryption succeeds)
   205→  if (data.type === "m.room.encrypted") {
   206→    return {
   207→      title: roomTitle,
   208→      message: `${senderName}: 🔒 Encrypted message`,
   209→      room_id: data.room_id,
   210→    };
   211→  }
   212→
   213→  // Handle regular messages
   214→  if (data.type === "m.room.message") {
   215→    return {
   216→      title: roomTitle,
   217→      message: formatMessageContent(data),
   218→      room_id: data.room_id,
   219→    };
   220→  }
   221→
   222→  // Handle reactions
   223→  if (data.type === "m.reaction") {
   224→    return {
   225→      title: roomTitle,
   226→      message: `${senderName} reacted to a message`,
   227→      room_id: data.room_id,
   228→    };
   229→  }
   230→
   231→  // Handle stickers
   232→  if (data.type === "m.sticker") {
   233→    return {
   234→      title: roomTitle,
   235→      message: `${senderName}: 🧩 Sticker`,
   236→      room_id: data.room_id,
   237→    };
   238→  }
   239→
   240→  // Handle call events
   241→  if (data.type === "m.call.invite") {
   242→    return {
   243→      title: roomTitle,
   244→      message: `${senderName} is calling you`,
   245→      room_id: data.room_id,
   246→    };
   247→  }
   248→
   249→  if (data.type === "m.call.hangup") {
   250→    return {
   251→      title: roomTitle,
   252→      message: `${senderName} ended the call`,
   253→      room_id: data.room_id,
   254→    };
   255→  }
   256→
   257→  // Handle room state events
   258→  if (data.type === "m.room.name") {
   259→    return {
   260→      title: roomTitle,
   261→      message: `${senderName} changed the room name`,
   262→      room_id: data.room_id,
   263→    };
   264→  }
   265→
   266→  if (data.type === "m.room.topic") {
   267→    return {
   268→      title: roomTitle,
   269→      message: `${senderName} changed the room topic`,
   270→      room_id: data.room_id,
   271→    };
   272→  }
   273→
   274→  if (data.type === "m.room.avatar") {
   275→    return {
   276→      title: roomTitle,
   277→      message: `${senderName} changed the room avatar`,
   278→      room_id: data.room_id,
   279→    };
   280→  }
   281→
   282→  // Handle pinned events
   283→  if (data.type === "m.room.pinned_events") {
   284→    return {
   285→      title: roomTitle,
   286→      message: `${senderName} updated pinned messages`,
   287→      room_id: data.room_id,
   288→    };
   289→  }
   290→
   291→  // Handle redaction (message deletion)
   292→  if (data.type === "m.room.redaction") {
   293→    return {
   294→      title: roomTitle,
   295→      message: `${senderName} deleted a message`,
   296→      room_id: data.room_id,
   297→    };
   298→  }
   299→
   300→  return undefined;
   301→};
