     1→import type {
     2→  EventTimelineItem,
     3→  RoomInterface,
     4→  TaskHandleInterface,
     5→  TimelineInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import {
     8→  DateDividerMode,
     9→  MessageType_Tags,
    10→  MsgLikeKind_Tags,
    11→  ReceiptType,
    12→  TimelineDiff_Tags,
    13→  TimelineFilter,
    14→  TimelineFocus,
    15→  TimelineItemContent_Tags,
    16→  TimelineReadReceiptTracking,
    17→} from "@unomed/react-native-matrix-sdk";
    18→import { useSetAtom } from "jotai";
    19→import { MatrixAtoms } from "modules/matrix-client/jotai";
    20→import { MatrixService } from "modules/matrix-client/services";
    21→import { getEventId } from "modules/matrix-client/utils";
    22→import { NavigationContainerRef } from "modules/navigation/const";
    23→import { TimelineAtoms } from "modules/timeline";
    24→import { useCallback, useEffect, useRef, useState } from "react";
    25→
    26→/** Maximum age for a verification request to be considered valid (5 minutes) */
    27→const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;
    28→
    29→/** Check if an event is a verification request */
    30→const isVerificationRequest = (event: EventTimelineItem): boolean => {
    31→  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
    32→  const kind = event.content.inner.content.kind;
    33→  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
    34→  const msgType = kind.inner.content.msgType;
    35→  return (
    36→    msgType?.tag === MessageType_Tags.Other &&
    37→    msgType.inner.msgtype === "m.key.verification.request"
    38→  );
    39→};
    40→
    41→/** Check if a verification request is recent enough to be handled */
    42→const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
    43→  const eventTimestamp = Number(event.timestamp);
    44→  const now = Date.now();
    45→  const age = now - eventTimestamp;
    46→  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
    47→};
    48→
    49→interface Props {
    50→  room: RoomInterface | undefined;
    51→  roomId: string;
    52→}
    53→
    54→export const useRoomTimeline = ({ room, roomId }: Props) => {
    55→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    56→  const [loadingMessage, setLoadingMessage] = useState(true);
    57→  /** Track processed verification request IDs to avoid duplicates */
    58→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
    59→  const [refreshing, setRefreshing] = useState(false);
    60→  const [updateTrigger, setUpdateTrigger] = useState(0);
    61→  const eventIdsRef = useRef<Set<string>>(new Set());
    62→  const timelineRef = useRef<TimelineInterface | null>(null);
    63→  const isPaginatingRef = useRef(false);
    64→  const timelinePaginateNumber = useRef<number>(20);
    65→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    66→  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
    67→
    68→  const upsertEvents = (
    69→    incoming: EventTimelineItem[],
    70→    position: "front" | "back" = "back",
    71→  ) => {
    72→    setEvents((prev) => {
    73→      const next = [...prev];
    74→      for (const e of incoming) {
    75→        const id = getEventId(e);
    76→        if (!id) continue;
    77→        const existingIndex = next.findIndex((item) => getEventId(item) === id);
    78→        if (existingIndex !== -1) {
    79→          next[existingIndex] = e;
    80→          continue;
    81→        }
    82→
    83→        eventIdsRef.current.add(id);
    84→        if (position === "front") next.unshift(e);
    85→        else next.push(e);
    86→      }
    87→      return next;
    88→    });
    89→  };
    90→
    91→  const handleVerificationRequest = (info: {
    92→    senderId: string;
    93→    flowId: string;
    94→  }) => {
    95→    setVerificationStatus("incomingRequest");
    96→    NavigationContainerRef.navigate("verifyUser", {
    97→      userId: info.senderId,
    98→      flowId: info.flowId,
    99→    });
   100→  };
   101→
   102→  const checkForVerificationRequests = useCallback(
   103→    (incoming: EventTimelineItem[]) => {
   104→      for (const event of incoming) {
   105→        if (event.isOwn) continue;
   106→
   107→        if (
   108→          !isVerificationRequest(event) ||
   109→          !isRecentVerificationRequest(event)
   110→        ) {
   111→          continue;
   112→        }
   113→
   114→        const flowId = getEventId(event);
   115→        if (!flowId) continue;
   116→
   117→        if (processedVerificationRequestsRef.current.has(flowId)) continue;
   118→
   119→        processedVerificationRequestsRef.current.add(flowId);
   120→
   121→        handleVerificationRequest({
   122→          senderId: event.sender,
   123→          flowId,
   124→        });
   125→
   126→        // Only handle one at a time
   127→        break;
   128→      }
   129→    },
   130→    [],
   131→  );
   132→
   133→  const markAsRead = async () => {
   134→    if (!room) return;
   135→
   136→    try {
   137→      await room.markAsRead(ReceiptType.Read);
   138→    } catch (error) {
   139→      console.error("Failed to mark room as read:", error);
   140→    }
   141→  };
   142→
   143→  const loadMoreMessages = async () => {
   144→    if (!room || !timelineRef.current) return;
   145→
   146→    isPaginatingRef.current = true;
   147→    setRefreshing(true);
   148→
   149→    try {
   150→      await timelineRef.current.paginateBackwards(
   151→        timelinePaginateNumber.current,
   152→      );
   153→      timelinePaginateNumber.current += 20;
   154→    } catch (error) {
   155→      console.error("Failed to load more messages:", error);
   156→    } finally {
   157→      setRefreshing(false);
   158→      isPaginatingRef.current = false;
   159→    }
   160→  };
   161→
   162→  useEffect(() => {
   163→    if (!room) return;
   164→    setPinnedEventIds([]);
   165→    MatrixService.getPinnedEventIds(roomId)
   166→      .then(setPinnedEventIds)
   167→      .catch(console.error);
   168→  }, [roomId]);
   169→
   170→  useEffect(() => {
   171→    if (!room) return;
   172→
   173→    // Reset state when room changes
   174→    setEvents([]);
   175→    eventIdsRef.current.clear();
   176→
   177→    let timelineListenerHandle: TaskHandleInterface | null = null;
   178→
   179→    const initRoomTimeline = async () => {
   180→      try {
   181→        const timeline = await room.timelineWithConfiguration({
   182→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
   183→          filter: new TimelineFilter.All(),
   184→          internalIdPrefix: undefined,
   185→          dateDividerMode: DateDividerMode.Daily,
   186→          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
   187→          reportUtds: false,
   188→        });
   189→
   190→        // Store timeline in ref for reuse in pagination
   191→        timelineRef.current = timeline;
   192→
   193→        await timeline.paginateBackwards(timelinePaginateNumber.current);
   194→        timelinePaginateNumber.current += 20;
   195→        setLoadingMessage(false);
   196→
   197→        // Set up timeline listener for real-time updates
   198→        timelineListenerHandle = await timeline.addListener({
   199→          onUpdate: (diffs) => {
   200→            markAsRead();
   201→            // Trigger re-render to update read receipts and other event properties
   202→            setUpdateTrigger((prev) => prev + 1);
   203→            diffs.forEach((diff) => {
   204→              const change = diff.tag;
   205→              switch (change) {
   206→                case TimelineDiff_Tags.Append: {
   207→                  const newItems = diff.inner.values;
   208→                  if (newItems.length) {
   209→                    const eventItems = newItems
   210→                      .map((i) => i.asEvent())
   211→                      .filter((i): i is EventTimelineItem => !!i);
   212→
   213→                    if (eventItems.length > 0) {
   214→                      upsertEvents(eventItems, "back");
   215→                      checkForVerificationRequests(eventItems);
   216→                    }
   217→                  }
   218→                  break;
   219→                }
   220→                case TimelineDiff_Tags.Insert: {
   221→                  const { value } = diff.inner;
   222→                  const ev = value.asEvent();
   223→                  if (ev) {
   224→                    upsertEvents([ev], "back");
   225→                    checkForVerificationRequests([ev]);
   226→                  }
   227→                  break;
   228→                }
   229→                case TimelineDiff_Tags.Set: {
   230→                  const { value } = diff.inner;
   231→                  const ev = value.asEvent();
   232→                  if (ev) {
   233→                    const id = getEventId(ev);
   234→                    if (!id) break;
   235→
   236→                    setEvents((prev) => {
   237→                      // Find event by ID to handle edits/deletions properly
   238→                      const existingIndex = prev.findIndex(
   239→                        (e) => getEventId(e) === id,
   240→                      );
   241→                      if (existingIndex !== -1) {
   242→                        const next = [...prev];
   243→                        next[existingIndex] = ev;
   244→                        return next;
   245→                      }
   246→                      // If not found and not tracked, add it
   247→                      if (!eventIdsRef.current.has(id)) {
   248→                        eventIdsRef.current.add(id);
   249→                        return [...prev, ev];
   250→                      }
   251→                      return prev;
   252→                    });
   253→                  }
   254→                  break;
   255→                }
   256→                case TimelineDiff_Tags.Remove: {
   257→                  const { index: removeIndex } = diff.inner;
   258→                  setEvents((prev) => {
   259→                    const next = prev.filter((_, idx) => idx !== removeIndex);
   260→                    eventIdsRef.current = new Set(
   261→                      next.map(getEventId).filter(Boolean) as string[],
   262→                    );
   263→                    return next;
   264→                  });
   265→                  break;
   266→                }
   267→                case TimelineDiff_Tags.PushFront: {
   268→                  const { value } = diff.inner;
   269→                  const ev = value.asEvent();
   270→                  if (ev) {
   271→                    upsertEvents([ev], "front");
   272→                    checkForVerificationRequests([ev]);
   273→                  }
   274→                  break;
   275→                }
   276→                case TimelineDiff_Tags.PushBack: {
   277→                  const { value } = diff.inner;
   278→                  const ev = value.asEvent();
   279→                  if (ev) {
   280→                    upsertEvents([ev], "back");
   281→                    checkForVerificationRequests([ev]);
   282→                  }
   283→                  break;
   284→                }
   285→                case TimelineDiff_Tags.Reset: {
   286→                  const resetItems = diff.inner.values;
   287→                  if (resetItems.length) {
   288→                    const eventItems = resetItems
   289→                      .map((i) => i.asEvent())
   290→                      .filter((i): i is EventTimelineItem => !!i);
   291→
   292→                    // Deduplicate events in case Reset contains duplicates
   293→                    const seenIds = new Set<string>();
   294→                    const uniqueEvents: EventTimelineItem[] = [];
   295→
   296→                    for (const event of eventItems) {
   297→                      const id = getEventId(event);
   298→                      if (id && !seenIds.has(id)) {
   299→                        seenIds.add(id);
   300→                        uniqueEvents.push(event);
   301→                      }
   302→                    }
   303→
   304→                    eventIdsRef.current = seenIds;
   305→                    setEvents(uniqueEvents);
   306→                  }
   307→                  break;
   308→                }
   309→                case TimelineDiff_Tags.Truncate: {
   310→                  const { length: cut } = diff.inner;
   311→                  setEvents((prev) => {
   312→                    const next = prev.slice(0, cut);
   313→                    eventIdsRef.current = new Set(
   314→                      next.map(getEventId).filter(Boolean) as string[],
   315→                    );
   316→                    return next;
   317→                  });
   318→                  break;
   319→                }
   320→                default:
   321→                  console.log("Unknown timeline change type:", change);
   322→              }
   323→            });
   324→          },
   325→        });
   326→      } catch (error) {
   327→        console.error("Failed to initialize room timeline:", error);
   328→        return null;
   329→      }
   330→    };
   331→
   332→    initRoomTimeline();
   333→
   334→    return () => {
   335→      timelineListenerHandle?.cancel?.();
   336→      timelineRef.current = null;
   337→    };
