/** Display the native iOS incoming call screen */
static displayIncomingCall(callInfo: {
  roomId: string;
  roomName: string;
  senderDisplayName: string;
}) {
  if (Platform.OS !== "ios") return;

  const callUUID = generateUUID();

  this.activeCallMap.set(callUUID, {
    roomId: callInfo.roomId,
    roomName: callInfo.roomName,
    senderDisplayName: callInfo.senderDisplayName,
  });

  RNCallKeep.displayIncomingCall(
    callUUID,
    callInfo.roomId,
    callInfo.senderDisplayName,
    "generic",
    true,
  );

  // Ring timeout: auto-end after 90 seconds if not answered
  const timeout = setTimeout(() => {
    RNCallKeep.reportEndCallWithUUID(
      callUUID,
      CONSTANTS.END_CALL_REASONS.UNANSWERED,
    );
    this.activeCallMap.delete(callUUID);
    this.ringTimeouts.delete(callUUID);
  }, 90000);
}
```

Shows how incoming calls are displayed to the user via iOS CallKit.

